"""AQS-END-001 decommissioning plan per system: drain, purge, dismantle (X-END-01, A-M-204). Reverse of the AQS-COM-001 order.
Drain mass = operating minus empty weight (AQS-BLD-013 STRUCT_ROWS); chemicals from the graph inflows (AQS-COM-001); gas units purged
with N2 to < 25 % LFL then < 1 % fuel (NFPA 2, NFPA 69), O2 units to < 23.5 % O2; tanks are confined spaces on entry (OSHA 1910.146).
Dismantled mass = empty weight, routed per AQS-END-002. Run after _commissioning.py and _struct_loads.py."""
import csv, json, os, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
for k in ('NFPA2_2023', 'NFPA69_2019', 'OSHA_1910_146', 'NFPA70E_2024'): cite(k)
C = list(csv.DictReader(open('docs-authority/inventory/COMMISSIONING.csv')))
SR = {r['unit']: r for r in json.load(open('docs-authority/inventory/STRUCT_ROWS.json'))}
order = list(dict.fromkeys(r['system'] for r in C))[::-1]
rows = []; md = ['# Decommissioning plan', '', 'Document number: AQS-END-001', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-END-01. Generated by `docs-authority/_decom.py`. Study. A-M-204. Material routes per AQS-END-002.', '',
      'Order: process systems first, utilities last (reverse of AQS-COM-001), so power, water, ventilation, gas detection and fire protection stay in service until the last process inventory is out. Every unit: LOTO and test-for-dead (NFPA 70E) before opening.', '',
      '| Step | System | Units | Drain (t) | Chemicals drained | Purge | Dismantled (t) |', '|---|---|---|---|---|---|---|']
for i, s in enumerate(order, 1):
    us = [r for r in C if r['system'] == s]; dr = 0; em = 0; ch = set(); pg = set()
    for r in us:
        x = SR.get(r['unit']) or {}; d = max(0, (x.get('op_kg') or 0) - (x.get('empty_kg') or 0)); dr += d; em += x.get('empty_kg') or 0
        cs = set(r['chemicals'].split()); ch |= cs
        p = 'N2 to < 25 % LFL, then < 1 % H2' if 'H2' in cs or 'hydrocarbon' in cs or 'CH3OH' in cs else ('N2/air to 19.5-23.5 % O2' if 'O2' in cs else ('air purge, scrubbed to vent (TLV)' if cs & {'HCl', 'Cl2', 'NO', 'HNO3'} else '-'))
        if p != '-': pg.add(p.split(',')[0])
        rows.append(dict(step=i, system=s, unit=r['unit'], drain_kg=round(d), chemicals=r['chemicals'], purge=p, dismantle_kg=round(x.get('empty_kg') or 0), confined_space='yes' if d > 500 else 'no'))
    md.append(f'| {i} | {s} | {len(us)} | {dr/1000:.2f} | {", ".join(sorted(ch)[:8])}{" …" if len(ch) > 8 else ""} | {"; ".join(sorted(pg)) or "-"} | {em/1000:.2f} |')
with open('docs-authority/inventory/DECOMMISSIONING.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
md += ['', f"Totals: drain {sum(r['drain_kg'] for r in rows)/1000:.1f} t, dismantle {sum(r['dismantle_kg'] for r in rows)/1000:.1f} t (equipment; building and water tower excluded). Liquids go to the plant's own recovery units while they still run (acid to HCl regeneration, metal liquor to EW), else to licensed treatment. Per unit: `docs-authority/inventory/DECOMMISSIONING.csv`.",
       'Last steps: H2/O2/CO2 banks drawn down into process use first, the rest vented at controlled rate through the relief headers (AQS-SAF-004) and N2 purged; ZnBr2 electrolyte drained to sealed drums for return (AQS-END-002); water tower drawn down last and kept for fire cover until the end.']
open('docs-authority/DECOMMISSIONING.md', 'w').write('\n'.join(md) + '\n'); print(len(rows))
